package net.battlespades.ugc;

import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import net.battlespades.entities.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import net.battlespades.player.*;
import net.battlespades.protocol.*;
import net.battlespades.world.MutableWorld;

/** Isolated editor owner. Socket/life admission and authenticated account resolution remain host boundaries. */
public final class UgcEditor {
    public interface Ports {void broadcast(GamePacket packet,Object exclude);void send(Object connection,GamePacket packet);void failure(Throwable error);}
    public interface Store {void checkpoint(String json)throws Exception;void save(UgcWorkspace.Snapshot snapshot)throws Exception;}
    public static Store store(UgcWorkspace workspace){return new Store(){public void checkpoint(String json)throws Exception{workspace.checkpoint(json);}public void save(UgcWorkspace.Snapshot snapshot)throws Exception{workspace.save(snapshot);}};}
    private final Thread owner=Thread.currentThread();private final UgcProject project;private final MutableWorld world;private final EntityRegistry entities;private final Executor ownerQueue,writer;private final Store store;private final Ports ports;private final java.util.function.Supplier<UgcWorkspace.Snapshot> capture;private final UgcCapacity capacity;private final MutableWorld.RemovalLease mutations;private final String ownerAccount;private final List<String> prefabs;
    private final Map<Object,String> connections=new IdentityHashMap<>();private final Map<UgcProject.Placement,Integer> markers=new LinkedHashMap<>();private final ArrayList<CompletableFuture<Boolean>> saves=new ArrayList<>();private Object host;private boolean metadataDirty,checkpoint,busy,closing,closed;private double nextCheckpoint;private long observedRevision;private CompletableFuture<Void> stopped;
    public UgcEditor(UgcProject project,MutableWorld world,byte[] source,EntityRegistry entities,List<String> prefabs,String ownerAccount,Executor ownerQueue,Executor writer,Store store,Ports ports){this(project,world,source,entities,prefabs,ownerAccount,ownerQueue,writer,store,ports,()->UgcWorkspace.capture(world,project));}
    public UgcEditor(UgcProject project,MutableWorld world,byte[] source,EntityRegistry entities,List<String> prefabs,String ownerAccount,Executor ownerQueue,Executor writer,Store store,Ports ports,java.util.function.Supplier<UgcWorkspace.Snapshot> capture){this.observedRevision=world.revision();this.capture=Objects.requireNonNull(capture);this.project=Objects.requireNonNull(project);this.world=Objects.requireNonNull(world);this.entities=Objects.requireNonNull(entities);this.prefabs=List.copyOf(prefabs);this.ownerAccount=Objects.requireNonNull(ownerAccount);this.ownerQueue=Objects.requireNonNull(ownerQueue);this.writer=Objects.requireNonNull(writer);this.store=Objects.requireNonNull(store);this.ports=Objects.requireNonNull(ports);capacity=UgcCapacity.fromVxl(source).track(world);mutations=world.observeTopology((c,s)->project.touch(),ports::failure);for(var p:project.placements())marker(p,false);}
    private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Editor accessed outside owner");if(closed)throw new IllegalStateException("Editor retired");}
    public UgcProject project(){owned();return project;}public UgcCapacity capacity(){owned();return capacity;}
    public void connected(Object connection,String authenticatedAccount){owned();if(closing)return;connections.put(Objects.requireNonNull(connection),Objects.requireNonNull(authenticatedAccount));if(ownerAccount.isEmpty()&&(host==null||!connections.containsKey(host)))host=connection;}
    public void left(Object connection){owned();connections.remove(connection);if(host==connection)host=null;}
    public boolean isHost(Object connection){owned();return !closing&&connections.containsKey(connection)&&(ownerAccount.isEmpty()?host==connection:ownerAccount.equals(connections.get(connection)));}
    public ClassCatalog.Selection selection(ClassCatalog.Selection requested){owned();var selected=new LinkedHashSet<String>();for(var n:requested.prefabs().stream().limit(5).toList())prefabs.stream().filter(p->p.equalsIgnoreCase(n)).findFirst().ifPresent(selected::add);int remaining=Math.max(0,5-Math.min(5,requested.prefabs().size()));var tools=requested.ugcTools().stream().limit(remaining).filter(i->i>=0&&i<19).distinct().toList();var base=ClassCatalog.normalize(13,requested.loadout(),List.of(),tools,13,List.of());return new ClassCatalog.Selection(13,base.loadout().stream().filter(t->t!=23).toList(),List.copyOf(selected),base.ugcTools());}
    public void reveal(Consumer<GamePacket> send){owned();UgcWire.batches(project).forEach(send);send.accept(UgcWire.objectives(project));for(var id:markers.values()){var entity=entities.get(id);if(entity!=null)send.accept(new CreateEntity(entity.toWireEntity()));}}
    private void changed(){metadataDirty=true;project.touch();}
    private void objectives(){ports.broadcast(UgcWire.objectives(project),null);}
    private void marker(UgcProject.Placement p,boolean announce){if(markers.containsKey(p))return;var placement=new EntityRegistry.Placement();placement.kind="ugc_marker";placement.state=p.item()>=4&&p.item()<=6||p.item()>=10&&p.item()<=12?3:p.item()>=7&&p.item()<=9||p.item()>=13&&p.item()<=15?2:1;var e=entities.place(29,p.x(),p.y(),p.z(),placement);e.ugcMode=UgcProject.modeId(p.mode());e.intProperties=List.of(p.item());markers.put(p,e.id());if(announce)ports.broadcast(new CreateEntity(e.toWireEntity()),null);}
    public boolean place(Object connection,PlayerLife player,SimplePackets.PlaceUGC packet,int loop){owned();int x=packet.x(),y=packet.y(),z=packet.z(),item=packet.ugc_item_id();if(!isHost(connection)||!player.alive()||!player.spawned()||player.inventory().tool()!=41||!player.selection().loadout().contains(41)||!player.toolEnabled(41)||!player.fire().state().raw()||x<0||x>=512||y<0||y>=512||z<0||z>=256||item<0||item>=19)return false;Vector at=player.position();double dx=at.x()-x,dy=at.y()-y,dz=at.z()-z;if(dx*dx+dy*dy+dz*dz>144)return false;boolean placing=packet.placing()!=0;if(placing&&(!world.solid(x,y,z+1)||world.solid(x,y,z)))return false;return placeAuthorized(connection,x,y,z,item,placing,loop);}
    /** Owner-side command path; callers must validate a live held tool before invoking for peer input. */
    public boolean placeAuthorized(Object connection,int x,int y,int z,int item,boolean placing,int loop){owned();if(!isHost(connection))return false;var result=placing?project.place(x,y,z,item):project.remove(x,y,z,item);if(result.isEmpty())return false;var p=result.orElseThrow();changed();ports.broadcast(new SimplePackets.PlaceUGC(loop,p.x(),p.y(),p.z(),p.item(),placing?1:0),null);if(placing)marker(p,true);else{var id=markers.remove(p);if(id!=null){entities.remove(id);ports.broadcast(new SimplePackets.DestroyEntity(id),null);}}objectives();return true;}
    public boolean targetMode(Object connection,int id){owned();if(!isHost(connection))return false;return targetMode(id);}
    public boolean targetMode(int id){owned();String mode;try{mode=UgcProject.target(UgcProject.modeCode(id));}catch(IllegalArgumentException invalid){return false;}project.targetMode(mode);changed();ports.broadcast(new SimplePackets.SetUGCEditMode(id),null);objectives();return true;}
    public boolean title(Object connection,String title){owned();if(!isHost(connection))return false;return title(title);}
    public boolean title(String title){owned();if(!project.title(title))return false;changed();return true;}
    public boolean palette(Object connection,UgcPackets.GroundColors palette){owned();if(!isHost(connection)||palette.colors().isEmpty()||palette.colors().size()>32)return false;project.groundColors(palette.colors().stream().map(c->List.of(c.r(),c.g(),c.b(),c.a())).toList());changed();ports.broadcast(palette,connection);return true;}
    public void checkpoint(){owned();if(!closing)metadataDirty=true;}
    private void observeRevision(){long revision=world.revision();if(revision!=observedRevision){observedRevision=revision;project.touch();metadataDirty=true;}}
    public void tick(double now){owned();observeRevision();if(!closing&&metadataDirty&&now>=nextCheckpoint){nextCheckpoint=now+1;checkpoint=true;drain();}}
    public CompletionStage<Boolean> save(Object connection){owned();if(!isHost(connection))return CompletableFuture.completedFuture(false);return flush();}
    /** Trusted owner-loop command; network callers use save(connection). */
    public CompletionStage<Boolean> flush(){owned();if(closing)return CompletableFuture.completedFuture(false);var result=new CompletableFuture<Boolean>();saves.add(result);drain();return result;}
    private void drain(){if(busy||closed)return;observeRevision();boolean full=!saves.isEmpty();if(!full&&!checkpoint){finishClose();return;}var waiters=full?List.copyOf(saves):List.<CompletableFuture<Boolean>>of();if(full)saves.clear();checkpoint=false;metadataDirty=false;UgcWorkspace.Snapshot snapshot;String json;try{snapshot=full?capture.get():null;json=full?null:project.json();}catch(RuntimeException error){metadataDirty=true;ports.failure(error);waiters.forEach(f->f.complete(false));finishClose();return;}busy=true;
        try{CompletableFuture.runAsync(()->{try{if(full)store.save(snapshot);else store.checkpoint(json);}catch(Exception error){throw new CompletionException(error);}},writer).whenCompleteAsync((unused,error)->{busy=false;if(error!=null){metadataDirty=true;ports.failure(error);}waiters.forEach(f->f.complete(error==null));drain();},ownerQueue);}catch(RejectedExecutionException error){busy=false;metadataDirty=true;ports.failure(error);waiters.forEach(f->f.complete(false));finishClose();}
    }
    /** Await before retiring the world, owner queue or worker; final flush follows every older write. */
    public CompletionStage<Void> deactivate(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Editor accessed outside owner");if(stopped!=null)return stopped;owned();closing=true;stopped=new CompletableFuture<>();var finalSave=new CompletableFuture<Boolean>();saves.add(finalSave);finalSave.whenComplete((ok,error)->{if(error!=null||!Boolean.TRUE.equals(ok))stopped.completeExceptionally(error==null?new IllegalStateException("UGC final save failed"):error);});drain();return stopped;}
    /** Startup rollback only: release listeners without writing an unpublished scene over the project. */
    void discard(){owned();if(busy||!saves.isEmpty())throw new IllegalStateException("Cannot discard an editor with pending writes");closing=true;stopped=new CompletableFuture<>();finishClose();}
    private void finishClose(){if(!closing||busy||!saves.isEmpty())return;mutations.close();capacity.close();for(var id:markers.values())entities.remove(id);markers.clear();connections.clear();host=null;closed=true;if(!stopped.isDone())stopped.complete(null);}
}
